-- Guest teleprompter script v3: ends on Kevin's goodnight rhyme.
-- src/lib/content/voice-scripts.ts mirrors this row. Recordings already made keep pointing at v2.
-- Until this runs, the app records against the newest version that exists (v2).
insert into public.voice_script_versions (script_id, version, body, word_count, published_at)
select id, 3, '["Once upon a time, in a little house at the edge of a sleepy town, there lived a family who loved stories more than anything. Every night, just after the moon peeked over the rooftops, someone would pick up a book, settle into the big blue chair, and begin to read.", "Do you remember the first story you ever loved? Maybe it was about a brave rabbit, or a girl who tumbled down a hole, or a bear who couldn’t stop thinking about honey. I still remember mine. I must have asked for it a hundred times.", "And then, one evening, something wonderful happened. The book began to glow, soft and golden. Oh, look at that! The pages are turning all by themselves. Hold on tight, everybody. Here we go.", "On Tuesday the fourteenth, at half past seven, Grandma Rosa, Uncle Theo and little June counted the stars together: one, two, three, four, five, all the way to twenty-seven before June fell fast asleep.", "Some stories are short. Some take three whole weeks to finish. But the best ones always feel like home. So find a cozy spot, take a slow breath, and whenever you’re ready, turn the page. The next adventure is waiting just for you. Goodnight, sleep tight, don’t let the bed bugs bite, and leave on the hall light."]'::jsonb, 222, now()
from public.voice_scripts where slug = 'guest_short.en'
on conflict (script_id, version) do nothing;
